    def build(i, s, e):
        if s == e:
            tree[i] = arr[s]
        else:
            mid = (s + e) // 2
            tree[i] = build(2 * i, s, mid) + build(2 * i + 1, mid + 1, e)
        return tree[i]
    build(1, 0, n - 1)
    return tree

def update_tree(tree, n, i, val, si=0, ei=None):
    if ei is None:
        ei = n - 1
    if si == ei:
        tree[i] = val
    else:
        mid = (si + ei) // 2
        if i <= mid:
            update_tree(tree, n, i, val, si, mid)
        else:
            update_tree(tree, n, i, val, mid + 1, ei)
        tree[i] = tree[2 * i] + tree[2 * i + 1]

def get_even_odd_count(tree, n, ql, qr, si=0, ei=None):
    if ei is None:
        ei = n - 1
    if ql > ei or qr < si:
        return 0, 0
    if ql <= si and qr >= ei:
        even = tree[2 * si] % 2 == 0
        return (tree[2 * si], 0) if even else (0, tree[2 * si])
    mid = (si + ei) // 2
    le, lo = get_even_odd_count(tree, n, ql, qr, si, mid)
    re, ro = get_even_odd_count(tree, n, ql, qr, mid + 1, ei)
    return le + re, lo + ro

